package com.hiakdhs323.localai;import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.util.*;
public class AiServerService extends Service{Process process;final String channel="local_ai";public void onCreate(){super.onCreate();createChannel();startForeground(42,notification("AI 서버 준비 중"));}public int onStartCommand(Intent i,int flags,int id){String model=i.getStringExtra("model");if(model!=null)startNative(model);return START_STICKY;}void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(channel,"Local AI Server",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(c);}}Notification notification(String s){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,channel):new Notification.Builder(this);return b.setContentTitle("Local AI Server").setContentText(s).setOngoing(true).setSmallIcon(android.R.drawable.stat_sys_download_done).build();}void startNative(String model){new Thread(()->{try{File bin=new File(getFilesDir(),"llama-server");if(!bin.exists())copyAsset("llama-server",bin);bin.setExecutable(true,false);File log=new File(getFilesDir(),"llama-server.log");ArrayList<String> cmd=new ArrayList<>();Collections.addAll(cmd,bin.getAbsolutePath(),"-m",model,"--host","0.0.0.0","--port","8080","-c","2048","-ngl","0");ProcessBuilder pb=new ProcessBuilder(cmd);pb.redirectErrorStream(true);pb.redirectOutput(ProcessBuilder.Redirect.appendTo(log));process=pb.start();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(42,notification("AI 서버 실행 중 · 포트 8080"));process.waitFor();}catch(Exception e){try(FileWriter w=new FileWriter(new File(getFilesDir(),"error.log"),true)){w.write(e+"\n");}catch(Exception ignored){}}}).start();}void copyAsset(String n,File d)throws Exception{try(InputStream in=getAssets().open(n);FileOutputStream out=new FileOutputStream(d)){byte[] b=new byte[1024*1024];int r;while((r=in.read(b))!=-1)out.write(b,0,r);}}public void onDestroy(){if(process!=null)process.destroy();super.onDestroy();}public IBinder onBind(Intent i){return null;}}
